import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Formik, Form, Field, ErrorMessage } from 'formik';
import * as Yup from 'yup';
import styled from 'styled-components';
import authService from '../services/authService';

const RegisterContainer = styled.div`
  max-width: 480px;
  margin: 0 auto;
  padding: 20px;
  background-color: white;
  min-height: 100vh;
`;

const Title = styled.h1`
  font-size: 24px;
  margin-bottom: 10px;
`;

const Subtitle = styled.p`
  color: #666;
  margin-bottom: 30px;
`;

const FormGroup = styled.div`
  margin-bottom: 20px;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 5px;
  color: #666;
  font-size: 14px;
`;

const StyledField = styled(Field)`
  width: 100%;
  padding: 12px;
  border: 1px solid #ddd;
  border-radius: 4px;
  font-size: 16px;
`;

const ErrorText = styled.div`
  color: red;
  font-size: 14px;
  margin-top: 5px;
`;

const RadioGroup = styled.div`
  display: flex;
  gap: 20px;
  margin-top: 10px;
`;

const RadioOption = styled.div`
  display: flex;
  align-items: center;
  gap: 5px;
`;

const RegisterButton = styled.button`
  width: 100%;
  background-color: #6c25ff;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 12px;
  font-size: 16px;
  cursor: pointer;
  margin-top: 20px;
  
  &:disabled {
    opacity: 0.7;
    cursor: not-allowed;
  }
`;

const AlertMessage = styled.div`
  background-color: #f8d7da;
  color: #721c24;
  padding: 10px;
  border-radius: 4px;
  margin-bottom: 20px;
`;

const validationSchema = Yup.object({
  fullName: Yup.string()
    .required('Full name is required'),
  phoneNumber: Yup.string()
    .matches(/^\d{10}$/, 'Phone number must be 10 digits')
    .required('Phone number is required'),
  email: Yup.string()
    .email('Invalid email address')
    .required('Email is required'),
  password: Yup.string()
    .min(6, 'Password must be at least 6 characters')
    .required('Password is required'),
  companyName: Yup.string(),
  isAgency: Yup.string().required('Please select an option')
});

const Register = () => {
  const navigate = useNavigate();
  const [registerError, setRegisterError] = useState('');

  const handleSubmit = async (values, { setSubmitting }) => {
    try {
      await authService.register({
        ...values,
        isAgency: values.isAgency === 'yes'
      });
      navigate('/account');
    } catch (error) {
      setRegisterError('Registration failed. Please check your information and try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <RegisterContainer>
      <Title>Create your PopX account</Title>
      <Subtitle>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</Subtitle>
      
      {registerError && <AlertMessage>{registerError}</AlertMessage>}
      
      <Formik
        initialValues={{ 
          fullName: '', 
          phoneNumber: '', 
          email: '', 
          password: '', 
          companyName: '',
          isAgency: 'yes'
        }}
        validationSchema={validationSchema}
        onSubmit={handleSubmit}
      >
        {({ isSubmitting, isValid, dirty }) => (
          <Form>
            <FormGroup>
              <Label htmlFor="fullName">Full Name*</Label>
              <StyledField type="text" id="fullName" name="fullName" placeholder="Marry Doe" />
              <ErrorMessage name="fullName" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label htmlFor="phoneNumber">Phone Number*</Label>
              <StyledField type="tel" id="phoneNumber" name="phoneNumber" placeholder="Marry Doe" />
              <ErrorMessage name="phoneNumber" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label htmlFor="email">Email Address*</Label>
              <StyledField type="email" id="email" name="email" placeholder="Marry Doe" />
              <ErrorMessage name="email" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label htmlFor="password">Password*</Label>
              <StyledField type="password" id="password" name="password" placeholder="Marry Doe" />
              <ErrorMessage name="password" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label htmlFor="companyName">Company Name</Label>
              <StyledField type="text" id="companyName" name="companyName" placeholder="Marry Doe" />
              <ErrorMessage name="companyName" component={ErrorText} />
            </FormGroup>
            
            <FormGroup>
              <Label>Are you an Agency?*</Label>
              <RadioGroup role="group" aria-labelledby="agency-radio-group">
                <RadioOption>
                  <Field type="radio" id="agency-yes" name="isAgency" value="yes" />
                  <label htmlFor="agency-yes">Yes</label>
                </RadioOption>
                <RadioOption>
                  <Field type="radio" id="agency-no" name="isAgency" value="no" />
                  <label htmlFor="agency-no">No</label>
                </RadioOption>
              </RadioGroup>
              <ErrorMessage name="isAgency" component={ErrorText} />
            </FormGroup>
            
            <RegisterButton 
              type="submit" 
              disabled={isSubmitting || !(isValid && dirty)}
            >
              Create Account
            </RegisterButton>
          </Form>
        )}
      </Formik>
    </RegisterContainer>
  );
};

export default Register;
